import React, { useEffect, useState, useRef } from 'react';
import { Link, useLocation } from 'react-router-dom';
import ReviewCard from '../components/ReviewCard';
import { fetchReviews } from '../api/reviewApi';
// Roulette is shown only on its dedicated page; remove from Home
import PostCard from '../components/PostCard';

// 리뷰 샘플 데이터
const sampleReviews = [
  {
    _id: 'r001', author: { username: '수아' }, title: '피부가 환해지는 비타민C 세럼', text: '싸걀!!!! 2주 썼는데 피부톤 ㅈㄴㅈㄴ 밝아졌어ㅜㅜ 흡수력 미쳤고 끈적임 1도 없음 ㄹㅇ 촉촉해서 아침에 바르면 화장이 겁나 잘먹어요ㅜ 완전 인생세럼 등극이야 여러분들도 꼭 사서 써보셈!! 알러빗ㅜㅜ', images: ['/images/비타민세럼리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 24, likes: 456, comments: 38, tags: ['세럼', '미백', '비타민C'], rating: 4.8
  },
  { _id: 'r002', author: { username: '민지' }, title: '촉촉함 미친 수분크림 추천', text: '건성인 나한테 인생템 찾음 아침까지 촉촉해서 감동받앗어 ㄹㅇㅜ 향도 은은하고 가성비까지 미침ㅋㅋㅋ 용량 넉넉해서 맘껏 덕지덕지 발라도 되고 진짜 이뻐용가리ㅜ 건성분들 이거 무조건 사세용!!', images: ['/images/cream.png'], createdAt: Date.now() - 1000 * 60 * 60 * 48, likes: 289, comments: 22, tags: ['수분크림', '보습', '건성피부'], rating: 4.5 },
  { _id: 'r003', author: { username: '윤서' }, title: '커버력 갑 쿠션 발견했어요', text: '얇게 발리는데 커버력 실화냐고ㅜㅜ 무너짐도 없고 자연광 아래서 ㅈㄴ 예뻐요 광채 미침ㅋㅋㅋ 여름에도 버틸듯!! 데일리 쿠션 찾는분들 이거 강추드려용 진짜 이거 없으면 어캄ㅜ', images: ['/images/파운데이션리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 72, likes: 523, comments: 45, tags: ['쿠션', '베이스', '커버력'], rating: 4.7 },
  { _id: 'r004', author: { username: '지우' }, title: '블랙헤드 싹 정리해주는 클렌징', text: '매일 쓰니까 모공이 점점 깨끗해지는게 느껴져ㅜㅜ 거품도 뽀송뽀송하고 세안 후에도 안땅겨서 너무 조아용ㅜ 모공고민 잇으면 이거 무조건 사야해!! 진짜 갓템이야 알러빗ㅜㅜ', images: ['/images/클렌징폼리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 5, likes: 367, comments: 29, tags: ['클렌징', '모공케어', '블랙헤드'], rating: 4.6 },
  { _id: 'r005', author: { username: '하은' }, title: '발색 미친 틴트 찾았다', text: '헐 색상 너무 이뻐서 뒤집어짐 발색도 미치고 지속력도 미침 ㄹㅇㅜ 입술 안건조해서 데일리로 딱이야!! 립덕후들 이거 찐이야 제발 사세요ㅜ 안사면 손해임 ㅈㄴ 이뻐용가리!!', images: ['/images/립스틱리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 120, likes: 612, comments: 51, tags: ['립스틱', '틴트', '립메이크업'], rating: 4.9 },
  { _id: 'r006', author: { username: '서연' }, title: '진정 갓팩 찾음', text: '피부 예민할때 이거 붙이면 바로 차분해져ㅜㅜ 진정효과 실화냐구ㅜ 매일 써도 가격 부담없어서 미침ㅋㅋ 민감피부분들 이거 강추드림!! 여러분들도 꼭 사서 쓰면 좋겟슨! 알러빗이야ㅜㅜ', images: ['/images/마스크팩리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 200, likes: 198, comments: 16, tags: ['마스크팩', '진정', '민감피부'], rating: 4.4 },
];

// 커뮤니티 샘플 데이터 (화장법, 정보, 잡담 등)
const sampleCommunityPosts = [
  {
    _id: 'c001', 
    author: { username: '뷰티마스터' }, 
    title: '🔥 입문자용 데일리 메이크업 순서 총정리!!', 
    text: '메이크업 처음 시작하는 분들 많이 헷갈리시죠?? 제가 순서 정리해드릴겡ㅋㅋ\n\n1️⃣ 스킨케어 (토너→세럼→크림)\n2️⃣ 선크림 (필수!!!)\n3️⃣ 프라이머\n4️⃣ 파운데이션/쿠션\n5️⃣ 컨실러\n6️⃣ 파우더\n7️⃣ 아이브로우\n8️⃣ 아이섀도우\n9️⃣ 아이라이너\n🔟 마스카라\n\n이 순서로 하면 무너짐 없이 하루종일 유지됨ㅋㅋ 궁금한거 있으면 댓글 ㄱㄱ!!', 
    images: [], 
    createdAt: Date.now() - 1000 * 60 * 60 * 3, 
    likes: 892, 
    comments: 156, 
    tags: ['메이크업순서', '입문자', '꿀팁'],
    category: 'tip'
  },
  {
    _id: 'c002', 
    author: { username: '피부과언니' }, 
    title: '피부 타입별 스킨케어 루틴 공유해요~', 
    text: '안녕하세용 피부과 다니면서 배운거 공유할겡ㅋㅋ\n\n💧건성: 수분크림 두껍게 + 오일 마무리\n🔥지성: 가벼운 수분젤 + 논코메도제닉 제품\n🌡️복합성: T존/U존 다르게 케어\n🌸민감성: 저자극 + 진정 성분 위주\n\n그리고 세안 미온수로!! 뜨거운물 ㄴㄴ 피부장벽 무너져요ㅜㅜ', 
    images: [], 
    createdAt: Date.now() - 1000 * 60 * 60 * 8, 
    likes: 567, 
    comments: 89, 
    tags: ['스킨케어', '피부타입', '루틴'],
    category: 'tip'
  },
  {
    _id: 'c003', 
    author: { username: '립덕후' }, 
    title: '요즘 핫한 립 조합 공유!!!!!', 
    text: '요즘 유행하는 립 조합 정리해봤어용ㅋㅋㅋ\n\n1. 롬앤 베어쥬시 + 페리페라 잉크틴트 = 청순 과즙미 뿜뿜\n2. 에스쁘아 노웨어 + 클리오 킬커버 = 고급진 mlbb\n3. 어뮤즈 듀틴트 + 헤라 센슈얼 = 촉촉 유리알 입술\n\n다들 한번 해봐요 찐 예쁨ㅋㅋㅋ 다른 조합 있으면 댓글로 공유해주세용!!', 
    images: [], 
    createdAt: Date.now() - 1000 * 60 * 60 * 15, 
    likes: 445, 
    comments: 78, 
    tags: ['립조합', '립메이크업', '트렌드'],
    category: 'talk'
  },
  {
    _id: 'c004', 
    author: { username: '올영러버' }, 
    title: '올영세일 뭐 사야되나요ㅠㅠ 추천좀!!', 
    text: '다음주 올영세일인데 뭐 사야할지 모르겟어요ㅜㅜ\n\n예산은 5만원 정도고 스킨케어 위주로 사고싶은데 추천좀요!!\n피부타입은 복합성이고 트러블 좀 있어요ㅠ\n\n선크림이랑 클렌징은 있어서 그거 빼고 추천해주시면 감사합니당!!', 
    images: [], 
    createdAt: Date.now() - 1000 * 60 * 60 * 2, 
    likes: 234, 
    comments: 167, 
    tags: ['올영세일', '추천', '질문'],
    category: 'question'
  },
  {
    _id: 'c005', 
    author: { username: '화장초보' }, 
    title: '아이라인 그리는거 너무 어려워요ㅠㅠ', 
    text: '아이라인 매일 그려보는데 왜이렇게 어렵죠...ㅠㅠ\n\n한쪽은 예쁘게 되는데 다른쪽은 항상 이상해요 진짜 미치겠음ㅋㅋㅋㅋ\n\n고수분들 꿀팁 좀 알려주세요ㅜ 펜라이너 쓰는데 추천 제품도 있으면 알려주세용!!', 
    images: [], 
    createdAt: Date.now() - 1000 * 60 * 60 * 6, 
    likes: 189, 
    comments: 134, 
    tags: ['아이라인', '초보', '질문'],
    category: 'question'
  },
  {
    _id: 'c006', 
    author: { username: '겨울맞이' }, 
    title: '건조한 겨울철 꿀피부 만드는 법 🌨️', 
    text: '겨울되니까 피부 건조해서 미치겠죠ㅜㅜ 제가 쓰는 방법 공유할겡!!\n\n1. 클렌징 후 3초 안에 토너 바르기 (수분 날아가기 전에!!)\n2. 에센스 2-3겹 레이어링\n3. 수분크림 + 페이셜오일 섞어바르기\n4. 일주일에 2번 수분팩\n5. 가습기 필수!!\n\n이거 한달 했더니 피부결 ㄹㅇ 좋아졌어요ㅋㅋ 다들 해봐요!!', 
    images: [], 
    createdAt: Date.now() - 1000 * 60 * 60 * 20, 
    likes: 678, 
    comments: 92, 
    tags: ['겨울스킨케어', '건조피부', '꿀팁'],
    category: 'tip'
  },
];

function Home() {
  const [latest, setLatest] = useState([]);
  const [posts, setPosts] = useState([]);
  const [reviews, setReviews] = useState(sampleReviews);
  const [communityPosts, setCommunityPosts] = useState(sampleCommunityPosts);
  const [activeTab, setActiveTab] = useState('review'); // 'review' or 'community'
  const [postType, setPostType] = useState('review'); // 글쓰기 타입
  const [communityCategory, setCommunityCategory] = useState('all'); // 커뮤니티 카테고리 필터
  const authorRef = useRef();
  const textRef = useRef();
  const fileRef = useRef();

  useEffect(() => {
    const load = async () => {
      try {
        const res = await fetchReviews({ page: 1, limit: 3 });
        setLatest(res.data);
      } catch (err) {
        console.error('fetch reviews failed', err);
      }
    };
    load();
  }, []);

  const location = useLocation();
  const params = new URLSearchParams(location.search);
  const showReviews = params.get('view') === 'reviews';

  // load posts from localStorage
  useEffect(() => {
    try {
      const raw = localStorage.getItem('blog_posts');
      if (raw) setPosts(JSON.parse(raw));
    } catch (e) { setPosts([]); }
  }, []);

  const savePosts = (list) => {
    try { localStorage.setItem('blog_posts', JSON.stringify(list)); } catch (e) {}
  };

  const handleCreatePost = async (e) => {
    e.preventDefault();
    const author = authorRef.current?.value || '익명';
    const text = textRef.current?.value || '';
    const file = fileRef.current?.files?.[0];
    let image = null;
    if (file) {
      image = await new Promise((res) => {
        const fr = new FileReader();
        fr.onload = () => res(fr.result);
        fr.readAsDataURL(file);
      });
    }
    
    if (postType === 'review') {
      // 리뷰 작성
      const newReview = { 
        _id: 'r' + Date.now(), 
        author: { username: author }, 
        title: text.split('\n')[0].slice(0, 30),
        text, 
        images: image ? [image] : [], 
        createdAt: Date.now(), 
        likes: 0,
        comments: 0,
        tags: [],
        rating: 0
      };
      setReviews(prev => [newReview, ...prev]);
    } else {
      // 커뮤니티 글 작성
      const newPost = { 
        _id: 'c' + Date.now(), 
        author: { username: author }, 
        title: text.split('\n')[0].slice(0, 50),
        text, 
        images: image ? [image] : [], 
        createdAt: Date.now(), 
        likes: 0,
        comments: 0,
        tags: [],
        category: 'talk'
      };
      setCommunityPosts(prev => [newPost, ...prev]);
    }
    
    // reset form
    if (authorRef.current) authorRef.current.value = '';
    if (textRef.current) textRef.current.value = '';
    if (fileRef.current) fileRef.current.value = '';
  };

  // 커뮤니티 카테고리 필터링
  const filteredCommunityPosts = communityCategory === 'all' 
    ? communityPosts 
    : communityPosts.filter(p => p.category === communityCategory);

  return (
    <div style={{ padding: 20 }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div>
          <h1 style={{ margin: 0 }}>✨ Review Community</h1>
          <p style={{ color: '#666' }}>실제 사람들이 쓰는 생생한 리뷰를 만나보세요.</p>
        </div>
        <div>
          <Link to="/coupons"><button style={{ padding: '10px 14px', borderRadius: 10, background: '#ff6b6b', color: '#fff', border: 'none' }}>룰렛 참여하기</button></Link>
        </div>
      </header>

      {/* 블로그 포스트 작성 섹션 */}
      <section style={{ marginTop: 24, marginBottom: 12 }}>
        <h2>새 게시물 작성</h2>
        <form onSubmit={handleCreatePost} style={{ display: 'grid', gridTemplateColumns: '1fr 120px', gap: 12, alignItems: 'start' }}>
          <div>
            <input ref={authorRef} placeholder="작성자 이름 (선택)" style={{ width: '100%', padding: 10, borderRadius: 8, border: '1px solid #ddd', marginBottom: 8 }} />
            <textarea ref={textRef} placeholder="무슨 생각을 공유하고 싶나요? (텍스트 입력)" style={{ width: '100%', minHeight: 100, padding: 10, borderRadius: 8, border: '1px solid #ddd' }} />
            <div style={{ marginTop: 8 }}>
              <input ref={fileRef} type="file" accept="image/*" />
            </div>
          </div>
          <div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              <button type="submit" style={{ padding: '10px 14px', borderRadius: 10, background: '#ff6b6b', color: '#fff', border: 'none', cursor: 'pointer' }}>게시하기</button>
              <Link to="/feed"><button type="button" style={{ padding: '10px 14px', borderRadius: 10, background: '#eee', border: 'none', cursor: 'pointer' }}>리뷰 보러가기</button></Link>
            </div>
          </div>
        </form>
      </section>

      {/* 포스트 피드 */}
      <section style={{ marginTop: 18 }}>
        <h2>최신 게시물</h2>
        <div style={{ display: 'grid', gap: 16, gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', marginTop: 12 }}>
          {posts.length === 0 ? (
            <p style={{ color: '#999' }}>아직 게시물이 없습니다. 첫 게시물을 작성해보세요!</p>
          ) : (
            posts.map(p => <PostCard key={p._id} post={p} />)
          )}
        </div>
      </section>

      {/* 기존 최신 리뷰 섹션 (하단으로 이동) - 기본적으로는 숨김, 쿼리 ?view=reviews 로 표시 */}
      {showReviews && (
        <section style={{ marginTop: 28 }}>
          <h2>최신 리뷰</h2>
          {latest.length === 0 ? (
            <p style={{ color: '#999' }}>최신 리뷰가 없습니다.</p>
          ) : (
            latest.map(r => <ReviewCard key={r._id} id={r._id} username={r.author?.username || '익명'} title={r.title} text={r.text} images={r.images} createdAt={r.createdAt} likes={r.likes} />)
          )}
        </section>
      )}

      {/* 룰렛: 전용 페이지에서만 표시됩니다 (Navbar -> 룰렛) */}
    </div>
  );
}

export default Home;
